Evelina, not another daughter volume.","checkedAt":"2026-11-01"}],"cover_url":"https://metadata.isbn.nl/ie_fcache/0000788944_De_Franse_dochter_2_710_130_0_0.jpg","edition_id":978200165,"bound_title":"De Franse dochter","reviewed_at":"2026-11-01T21:37:32+00:00","bound_isbn13":"9789046833520","evidence_url":"https://metadata.isbn.nl/1920488/de-franse-dochter.html","review_batch":"nl007-reviewed-batch-08-20261101","review_status":"approved","bound_language":"nld","card_cover_url":null,"bound_author_id":978300050},"before_row":null},{"key":{"work_id":978100107,"language":"nl"},"seq":4,"relation":"catalog_work_descriptions","after_row":{"text":"Na het overlijden van haar grootmoeder krijgt Blake een stukje zilveren stof en een oud kledingontwerp in handen. De voorwerpen zijn haar weinige aanknopingspunten voor een onbekende familiegeschiedenis. Haar zoektocht raakt aan het leven van Evelina, die in het Parijs van 1937 haar droom als ontwerpster probeert waar te maken. Het verhaal verbindt hun verschillende tijden via de vraag welke geschiedenis achter de bewaarde voorwerpen schuilgaat.","work_id":978100107,"evidence":[{"url":"https://metadata.isbn.nl/1920488/de-franse-dochter.html","fact":"Paperback ISBN 9789046833520 verschijningsdatum 04/02/2025 NUR 302 Vertaalde literaire roman, novelle imprint Oceaan uitgever Park Uitgevers taal Engels","sha256":"81df92bb346fb416e1aed0f1cc7a8a6a51cdbc15c7286a1ee2ed1211fb430bf9","checkedAt":"2026-11-01T20:43:09.773Z","sourceAuthors":"Soraya Lane"},{"url":"https://metadata.isbn.nl/1920488/de-franse-dochter.html","fact":"Work-bound content reviewed; original factual Dutch summary, not source quotation or title-derived content.","checkedAt":"2026-11-01T21:37:32Z"}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://metadata.isbn.nl/1920488/de-franse-dochter.html","reviewed_at":"2026-11-01T21:37:32+00:00","source_name":"Bibliografische bron; oorspronkelijke gecontroleerde samenvatting","source_type":"official_catalog","review_batch":"nl007-reviewed-batch-08-20261101","review_status":"approved","bound_author_id":978300050},"before_row":null},{"key":{"id":978100108},"seq":5,"relation":"works","after_row":{"id":978100108,"title":"Het geschenk","cover_id":null,"author_id":978300051,"work_type":null,"source_type":"lumiscore_native","open_library_id":null,"first_publish_year":null,"native_identity_key":"nl-reviewed-isbn:9789025318604"},"before_row":null},{"key":{"id":978200166},"seq":6,"relation":"editions","after_row":{"id":978200166,"title":"Het geschenk","isbn_10":null,"isbn_13":"9789025318604","work_id":978100108,"cover_id":null,"language":"nld","publisher":"Querido","publish_date":null,"open_library_edition_id":null},"before_row":null},{"key":{"edition_id":978200166},"seq":7,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":978100108,"evidence":[{"url":"https://metadata.isbn.nl/1963074/het-geschenk.html","fact":"Paperback ISBN 9789025318604 verschijningsdatum 04/06/2025 NUR 301 Literaire roman, novelle imprint Querido uitgever Singel Uitgeverijen taal Nederlands","sha256":"3d50965652b5e5f46e5598e88d0cec27ae6c7be12e362fcae6eae88ff9f5ef54","checkedAt":"2026-11-01T20:43:11.995Z","sourceAuthors":"Gaea Schoeters"},{"url":"https://metadata.isbn.nl/ie_fcache/0000709382_Het_geschenk_2_710_130_0_0.jpg","fact":"Exact edition block and human visual review; same observed provider image stem for medium variant.","bytes":96245,"sha256":"2f38265a2fc71e900f2ae33a00578ceaaeda2a7e1416121bd2ad5a7e2f65989b","checkedAt":"2026-11-01T21:23:57.203Z"}],"cover_url":"https://metadata.isbn.nl/ie_fcache/0000709382_Het_geschenk_2_710_130_0_0.jpg","edition_id":978200166,"bound_title":"Het geschenk","reviewed_at":"2026-11-01T21:37:32+00:00","bound_isbn13":"9789025318604","evidence_url":"https://metadata.isbn.nl/1963074/het-geschenk.html","review_batch":"nl007-reviewed-batch-08-20261101","review_status":"approved","bound_language":"nld","card_cover_url":null,"bound_author_id":978300051},"before_row":null},{"key":{"work_id":978100108,"language":"nl"},"seq":8,"relation":"catalog_work_descriptions","after_row":{"text":"In Berlijn duiken plotseling overal olifanten op. Ze blijken een geschenk van de president van Botswana, bedoeld als reactie op strengere Duitse regels voor de invoer van jachttrofeeën. Met twintigduizend dieren krijgt de stad een probleem dat zich moeilijk laat wegpraten. De roman volgt de botsing tussen politieke overtuigingen en een ontregelende werkelijkheid, waarin de gevolgen van een besluit onverwacht dichtbij komen te staan.","work_id":978100108,"evidence":[{"url":"https://metadata.isbn.nl/1963074/het-geschenk.html","fact":"Paperback ISBN 9789025318604 verschijningsdatum 04/06/2025 NUR 301 Literaire roman, novelle imprint Querido uitgever Singel Uitgeverijen taal Nederlands","sha256":"3d50965652b5e5f46e5598e88d0cec27ae6c7be12e362fcae6eae88ff9f5ef54","checkedAt":"2026-11-01T20:43:11.995Z","sourceAuthors":"Gaea Schoeters"},{"url":"https://metadata.isbn.nl/1963074/het-geschenk.html","fact":"Work-bound content reviewed; original factual Dutch summary, not source quotation or title-derived content.","checkedAt":"2026-11-01T21:37:32Z"}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://metadata.isbn.nl/1963074/het-geschenk.html","reviewed_at":"2026-11-01T21:37:32+00:00","source_name":"Bibliografische bron; oorspronkelijke gecontroleerde samenvatting","source_type":"official_catalog","review_batch":"nl007-reviewed-batch-08-20261101","review_status":"approved","bound_author_id":978300051},"before_row":null},{"key":{"id":978100109},"seq":9,"relation":"works","after_row":{"id":978100109,"title":"Grondwerk","cover_id":null,"author_id":978300052,"work_type":null,"source_type":"lumiscore_native","open_library_id":null,"first_publish_year":null,"native_identity_key":"nl-reviewed-isbn:9789025475598"},"before_row":null},{"key":{"id":978200167},"seq":10,"relation":"editions","after_row":{"