84be3e93c3","checkedAt":"2026-11-01T20:43:20.891Z","sourceAuthors":"Joris van Casteren"},{"url":"https://metadata.isbn.nl/ie_fcache/0000648669_De_mensheid_zal_nog_van_mij_horen_2_710_130_0_0.jpg","fact":"Exact edition block and human visual review; same observed provider image stem for medium variant.","bytes":160691,"sha256":"b58f43a74d541398a2e097a84fe898bb0519dbe1cf22bcebd8f190e927bf941a","checkedAt":"2026-11-01T21:24:02.579Z"}],"cover_url":"https://metadata.isbn.nl/ie_fcache/0000648669_De_mensheid_zal_nog_van_mij_horen_2_710_130_0_0.jpg","edition_id":978200170,"bound_title":"De mensheid zal nog van mij horen","reviewed_at":"2026-11-01T21:37:32+00:00","bound_isbn13":"9789403180915","evidence_url":"https://metadata.isbn.nl/1798629/de-mensheid-zal-nog-van-mij-horen.html","review_batch":"nl007-reviewed-batch-08-20261101","review_status":"approved","bound_language":"nld","card_cover_url":null,"bound_author_id":978300055},"before_row":null},{"key":{"work_id":978100112,"language":"nl"},"seq":24,"relation":"catalog_work_descriptions","after_row":{"text":"Joris van Casteren ontdekt een archief met de dagboeken van honderden onbekende Nederlanders. Vijf jaar lang leest hij hun persoonlijke verslagen en probeert hij de levens achter die bladzijden te begrijpen. De schrijvers gebruiken hun dagboek als een besloten ruimte, maar hopen soms ook op een toekomstige lezer. Het boek volgt Van Casterens onderzoek naar stemmen die buiten de gebruikelijke geschiedschrijving vallen en toch gehoord willen worden.","work_id":978100112,"evidence":[{"url":"https://metadata.isbn.nl/1798629/de-mensheid-zal-nog-van-mij-horen.html","fact":"Paperback ISBN 9789403180915 Nieuwe editie verschijningsdatum 08/10/2024 NUR 320 Literaire non-fictie algemeen uitgever Bezige Bij b.v., Uitgeverij De taal Nederlands","sha256":"d93e60227d96ebee280b167501b25101bb4f8ff3ff7fa1d7f31e9f84be3e93c3","checkedAt":"2026-11-01T20:43:20.891Z","sourceAuthors":"Joris van Casteren"},{"url":"https://metadata.isbn.nl/17986