nguage":"nl"},"seq":32,"relation":"catalog_work_descriptions","after_row":{"text":"Een vrouw wacht bij de zee op Noah, de twaalfjarige jongen voor wie zij al sinds zijn eerste levensjaar zorgt. Aan de vloedlijn blijft zij uitkijken naar wat een volgende golf kan brengen. Rond dat wachten ontvouwt zich een verhaal over de mensen die met elkaar verbonden raken en over wat zij kunnen verliezen. De roman benadert hun onderlinge banden vanuit verschillende stemmen, zonder het gemis eenvoudig te kunnen oplossen.","work_id":978100114,"evidence":[{"url":"https://metadata.isbn.nl/2117378/wachten-op-noah.html","fact":"Paperback ISBN 9789022342435 verschijningsdatum 06/10/2026 NUR 301 Literaire roman, novelle imprint Manteau uitgever Standaard Uitgeverij - Algemeen taal Nederlands","sha256":"936ac1fa27336b865cf9d34fad5fbe9c3c43b937ccd4234c2d07412969f6cdb3","checkedAt":"2026-11-01T20:43:27.359Z","sourceAuthors":"Ish Ait Hamou"},{"url":"https://metadata.isbn.nl/2117378/wachten-op-noah.html","fact":"Work-bound content reviewed; original factual Dutch summary, not source quotation or title-derived content.","checkedAt":"2026-11-01T21:37:32Z"}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://metadata.isbn.nl/2117378/wachten-op-noah.html","reviewed_at":"2026-11-01T21:37:32+00:00","source_name":"Bibliografische bron; oorspronkelijke gecontroleerde samenvatting","source_type":"official_catalog","review_batch":"nl007-reviewed-batch-08-20261101","review_status":"approved","bound_author_id":978300056},"before_row":null},{"key":{"id":978100115},"seq":33,"relation":"works","after_row":{"id":978100115,"title":"Een winter vol verrassingen","cover_id":null,"author_id":978300057,"work_type":null,"source_type":"lumiscore_native","open_library_id":null,"first_publish_year":null,"native_identity_key":"nl-reviewed-isbn:9789049211660"},"before_row":null},{"key":{"id":978200173},"seq":34,"relation":"editions","after_row":{"id":978200173,"title":"Een winter vol v