ken leven. Zijn hond Rusty en zijn bezoekjes aan het café van Betty bieden nog wat houvast. Betty wil hem graag dichterbij laten komen, maar Jack is aan zijn eenzaamheid gewend geraakt. Wanneer zijn kleindochter Flora onverwacht verschijnt, krijgt de naderende kerst een andere betekenis. Het verhaal volgt hoe verschillende mensen zoeken naar gezelschap in een periode die juist verbondenheid lijkt te verlangen.","work_id":978100115,"evidence":[{"url":"https://metadata.isbn.nl/2076746/een-winter-vol-verrassingen.html","fact":"Hardback ISBN 9789049211660 verschijningsdatum 29/09/2026 NUR 302 Vertaalde literaire roman, novelle imprint Boekerij uitgever Meulenhoff Boekerij B.V. taal Engels","sha256":"5ee253888359fd1605ca9d3b6e651736027cdc14e2fc6fb2167349a4b0064650","checkedAt":"2026-11-01T20:43:31.702Z","sourceAuthors":"Santa Montefiore"},{"url":"https://metadata.isbn.nl/2076746/een-winter-vol-verrassingen.html","fact":"Work-bound content reviewed; original factual Dutch summary, not source quotation or title-derived content.","checkedAt":"2026-11-01T21:37:32Z"}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://metadata.isbn.nl/2076746/een-winter-vol-verrassingen.html","reviewed_at":"2026-11-01T21:37:32+00:00","source_name":"Bibliografische bron; oorspronkelijke gecontroleerde samenvatting","source_type":"official_catalog","review_batch":"nl007-reviewed-batch-08-20261101","review_status":"approved","bound_author_id":978300057},"before_row":null},{"key":{"id":978100116},"seq":37,"relation":"works","after_row":{"id":978100116,"title":"De lamzak","cover_id":null,"author_id":978300058,"work_type":null,"source_type":"lumiscore_native","open_library_id":null,"first_publish_year":null,"native_identity_key":"nl-reviewed-isbn:9789044662467"},"before_row":null},{"key":{"id":978200174},"seq":38,"relation":"editions","after_row":{"id":978200174,"title":"De lamzak","isbn_10":null,"isbn_13":"9789044662467","work_id":978100116,"cover_id":null,"langu