russel wacht een naakte molrat op verdere instructies voor haar missie vanuit de Hoorn van Afrika. Wanneer een mens bij haar gangenstelsel verschijnt, vertrouwt zij hem haar verhaal toe. Boven de grond ontstaan ondertussen steeds meer zinkgaten. Vanuit die verborgen wereld ontvouwt zich een geschiedenis die de vertrouwde stad anders laat bekijken en vragen oproept over wat er onder haar oppervlak gebeurt.","source_type":"official_catalog","source_name":"Bibliografische bron; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/1957805/grondwerk.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T21:37:32Z","review_batch":"nl007-reviewed-batch-08-20261101","evidence":[{"url":"https://metadata.isbn.nl/1957805/grondwerk.html","sha256":"c421634652968b0b80cdf27111bdd556cac105c1086c06fc49608be03b6f92b4","checkedAt":"2026-11-01T20:43:14.133Z","fact":"Paperback ISBN 9789025475598 verschijningsdatum 10/06/2025 NUR 300 Literaire fictie algemeen 301 Literaire roman, novelle imprint Atlas Contact uitgever Atlas Contact, Uitgeverij taal Nederlands","sourceAuthors":"Tijl Nuyts"},{"url":"https://metadata.isbn.nl/1957805/grondwerk.html","checkedAt":"2026-11-01T21:37:32Z","fact":"Work-bound content reviewed; original factual Dutch summary, not source quotation or title-derived content."}]}},{"relation":"works","ref":"work:new-alsdedieren","key":{"id":978100110},"before":null,"after":{"id":978100110,"title":"Als de dieren","cover_id":null,"author_id":978300053,"work_type":null,"source_type":"lumiscore_native","open_library_id":null,"first_publish_year":null,"native_identity_key":"nl-reviewed-isbn:9789493320833"}},{"relation":"editions","ref":"edition:9789493320833","key":{"id":978200168},"before":null,"after":{"id":978200168,"title":"Als de dieren","isbn_10":null,"isbn_13":"9789493320833","work_id":978100110,"cover_id":null,"language":"nld","publisher":"Das Mag Uitgeverij B.V.","publish_date":null,"