n hen verdwijnen, wordt het onderzoek opvallend snel afgesloten. Privédetective Diane neemt daar geen genoegen mee en raakt steeds sterker op Jeremy gericht. Hun wegen kruisen in een verhaal waarin persoonlijke geschiedenis en de aantrekkingskracht van radicale ideeën met elkaar verweven raken.","source_type":"official_catalog","source_name":"Bibliografische bron; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/1925984/de-rode-koe.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T21:37:32Z","review_batch":"nl007-reviewed-batch-08-20261101","evidence":[{"url":"https://metadata.isbn.nl/1925984/de-rode-koe.html","sha256":"9aecdffe06fd9adf9efec75abdbdc4bf40edffa75840ca904efd0a8769e11858","checkedAt":"2026-11-01T20:43:18.603Z","fact":"Paperback ISBN 9789044545395 verschijningsdatum 14/03/2025 NUR 301 Literaire roman, novelle imprint De Geus uitgever Singel Uitgeverijen taal Nederlands","sourceAuthors":"Hans Depelchin"},{"url":"https://metadata.isbn.nl/1925984/de-rode-koe.html","checkedAt":"2026-11-01T21:37:32Z","fact":"Work-bound content reviewed; original factual Dutch summary, not source quotation or title-derived content."}]}},{"relation":"works","ref":"work:new-demensheidzalnogvanmijhoren","key":{"id":978100112},"before":null,"after":{"id":978100112,"title":"De mensheid zal nog van mij horen","cover_id":null,"author_id":978300055,"work_type":null,"source_type":"lumiscore_native","open_library_id":null,"first_publish_year":null,"native_identity_key":"nl-reviewed-isbn:9789403180915"}},{"relation":"editions","ref":"edition:9789403180915","key":{"id":978200170},"before":null,"after":{"id":978200170,"title":"De mensheid zal nog van mij horen","isbn_10":null,"isbn_13":"9789403180915","work_id":978100112,"cover_id":null,"language":"nld","publisher":"Bezige Bij b.v., Uitgeverij De","publish_date":null,"open_library_edition_id":null}},{"relation":"catalog_edition_metadata","ref":"meta