emmen die buiten de gebruikelijke geschiedschrijving vallen en toch gehoord willen worden.","source_type":"official_catalog","source_name":"Bibliografische bron; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/1798629/de-mensheid-zal-nog-van-mij-horen.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T21:37:32Z","review_batch":"nl007-reviewed-batch-08-20261101","evidence":[{"url":"https://metadata.isbn.nl/1798629/de-mensheid-zal-nog-van-mij-horen.html","sha256":"d93e60227d96ebee280b167501b25101bb4f8ff3ff7fa1d7f31e9f84be3e93c3","checkedAt":"2026-11-01T20:43:20.891Z","fact":"Paperback ISBN 9789403180915 Nieuwe editie verschijningsdatum 08/10/2024 NUR 320 Literaire non-fictie algemeen uitgever Bezige Bij b.v., Uitgeverij De taal Nederlands","sourceAuthors":"Joris van Casteren"},{"url":"https://metadata.isbn.nl/1798629/de-mensheid-zal-nog-van-mij-horen.html","checkedAt":"2026-11-01T21:37:32Z","fact":"Work-bound content reviewed; original factual Dutch summary, not source quotation or title-derived content."}]}},{"relation":"works","ref":"work:new-dius","key":{"id":978100113},"before":null,"after":{"id":978100113,"title":"Dius","cover_id":null,"author_id":942300649,"work_type":null,"source_type":"lumiscore_native","open_library_id":null,"first_publish_year":null,"native_identity_key":"nl-reviewed-isbn:9789403133836"}},{"relation":"editions","ref":"edition:9789403133836","key":{"id":978200171},"before":null,"after":{"id":978200171,"title":"Dius","isbn_10":null,"isbn_13":"9789403133836","work_id":978100113,"cover_id":null,"language":"nld","publisher":"Bezige Bij b.v., Uitgeverij De","publish_date":null,"open_library_edition_id":null}},{"relation":"catalog_edition_metadata","ref":"metadata:9789403133836","key":{"edition_id":"@edition:9789403133836"},"before":null,"after":{"edition_id":"@edition:9789403133836","work_id":978100113,"bound_author_id":942300649,"bound_title":"Dius","bound